/** Icons that point a way: drawn turned round for right-to-left languages. */
const MIRRORED = new Set(["arrow_back","arrow_back_ios","arrow_forward","arrow_forward_ios","arrow_right_alt","branding_watermark","chevron_left","chevron_right","first_page","format_list_bulleted","format_list_numbered","help","help_outline","keyboard_arrow_left","keyboard_arrow_right","last_page","launch","library_books","navigate_before","navigate_next","note_add","notes","open_in_new","redo","rotate_left","rotate_right","send","short_text","sort","subject","undo","wrap_text"]);

// A rounded square outline, for a name that isn't in the set.
const PLACEHOLDER = '<rect x="5" y="5" width="14" height="14" rx="3" fill="none" stroke="currentColor" stroke-width="2"/>';
const warned = new Set();

/** Whether `name` is in the set. */
export function hasIcon(name) {
  return Object.prototype.hasOwnProperty.call(ICONS, name);
}

/** The names of every icon in the set. */
export function iconNames() {
  return Object.keys(ICONS);
}

/**
 * An inline <svg> of the Material icon `name` (such as 'arrow_back', 'more_vert', 'share'), in the
 * text color (currentColor). Hidden from screen readers unless `label` is given, which names it.
 * Icons that point a way are turned round for right-to-left languages.
 * @example button.append(icon('share'));  icon('lock', { size: 18, label: t('locked') })
 * @param {string} name
 * @param {{ size?: number, label?: string }} [options]
 * @returns {SVGSVGElement}
 */
/** Each icon's <svg>, parsed the first time it is drawn. */
const parsed = new Map();

export function icon(name, { size = 24, label } = {}) {
  let body = ICONS[name];
  if (body === undefined) {
    body = PLACEHOLDER;
    if (!warned.has(name)) {
      warned.add(name);
      console.warn(`Icon "${name}" isn't in core/icons.js yet: run node tools/build-icons.mjs --js`);
    }
  }
  // Parsed once per icon, then copied: a long list (a result of 300 files) draws hundreds.
  let shape = parsed.get(body);
  if (!shape) {
    const template = document.createElement('template');
    template.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor">${body}</svg>`;
    shape = template.content.firstChild;
    parsed.set(body, shape);
  }
  const svg = document.importNode(shape, true);
  svg.setAttribute('width', String(size));
  svg.setAttribute('height', String(size));
  svg.setAttribute('class', 'icon');
  svg.dataset.icon = name;
  svg.setAttribute('focusable', 'false');
  if (MIRRORED.has(name)) {
    svg.classList.add('icon-mirrored');
    if (getDirection() === 'rtl') svg.style.transform = 'scaleX(-1)';
  }
  if (label) {
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', label);
  } else {
    svg.setAttribute('aria-hidden', 'true');
  }
  return svg;
}
